    PRIVATE_ETH_CELL c;

    function setUp() public {
        c = new PRIVATE_ETH_CELL();
    }

    function _run(uint256 minSum, uint256 amount, uint256 am) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        vm.assume(amount >= am);
        vm.assume(amount >= minSum);
        try c.SetLogFile(address(this)) {} catch { return; }
        try c.SetMinSum(minSum) {} catch { return; }
        try c.Deposit{value: amount}() {} catch { return; }
        uint256 b0;
        try c.balances(address(this)) returns (uint256 __r) { b0 = __r; } catch { return; }
        uint e0 = address(c).balance;
        bool reverted;
        try c.Collect(am) { reverted = false; } catch { reverted = true; }
        uint256 b1;
        try c.balances(address(this)) returns (uint256 __r) { b1 = __r; } catch { return; }
        uint e1 = address(c).balance;
        assertTrue(!reverted && b1 == b0 - am && e0 - e1 == am);
    }

    function testFuzz_run(uint256 minSum, uint256 amount, uint256 am) public {
        _run(minSum, amount, am);
    }

    receive() external payable {}

    fallback() external payable {}
